<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Mail/ReceptionWorker.php';require dirname(__DIR__).'/app/Notices/Board.php';
use TNL\Mail\Reception;use TNL\Mail\ReceptionWorker;use TNL\Notices\Board;use TNL\Admin\Users;use TNL\Admin\Settings;
function checkRN(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo "PASS: $label\n";}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);Users::init($db);Settings::init($db);Settings::set($db,'company_domain','example.test');foreach(['jose','carlos','other'] as $name)Users::create($db,['username'=>$name,'display_name'=>ucfirst($name),'job_title'=>'Contador','domain'=>'example.test','password'=>'test-password-only']);Reception::init($db);$storage=sys_get_temp_dir().'/tnl-reception-'.bin2hex(random_bytes(6));mkdir($storage,0700);$owner='admin:1';Settings::set($db,'reception_owner',$owner);Settings::set($db,'reception_enabled','1');$wire=Reception::outbound($db,$owner,1,['client@outside.test'],$storage);Reception::link($db,$owner,'<sent@example.test>',$wire['token']);$base=['headers'=>['from'=>'client@outside.test','to'=>'communications@example.test','subject'=>'Consulta','message-id'=>'<reply@outside.test>','in-reply-to'=>'<sent@example.test>'],'body'=>'Mi respuesta','html'=>'<p>Mi respuesta</p>'];
$r=Reception::ingest($db,$owner,99,1,$base,$storage);checkRN($r['user_id']===1,'shared SMTP reply routes to originating employee by RFC reference');checkRN(Reception::read($db,1,2)===null&&Reception::read($db,1,1)!==null,'shared inbox read is isolated by assignee');checkRN(Reception::ingest($db,$owner,99,1,$base,$storage)['duplicate'],'same UID is not imported twice');$cross=$base;$cross['headers']['message-id']='<other@outside.test>';$cross['headers']['from']='other@outside.test';checkRN(Reception::ingest($db,$owner,99,2,$cross,$storage)['user_id']===0,'another client cannot reuse a conversation identifier');
$marker=$base;$marker['headers']['message-id']='<marker@outside.test>';unset($marker['headers']['in-reply-to']);$marker['html']='<!-- tnl-route='.$wire['route_marker'].' -->';checkRN(Reception::ingest($db,$owner,99,3,$marker,$storage)['user_id']===1,'signed hidden marker works when reply references are absent');$marker['headers']['message-id']='<tampered@outside.test>';$marker['html']='<!-- tnl-route='.substr($wire['route_marker'],0,-1).(str_ends_with($wire['route_marker'],'a')?'b':'a').' -->';checkRN(Reception::ingest($db,$owner,99,4,$marker,$storage)['user_id']===0,'tampered marker cannot assign a user');
$direct=$base;$direct['headers']['message-id']='<direct@outside.test>';$direct['headers']['to']='carlos@example.test';checkRN(Reception::ingest($db,$owner,99,5,$direct,$storage)['user_id']===2,'same client writing Carlos explicitly does not route to Jose');
$new=$base;$new['headers']['from']='newclient@outside.test';$new['headers']['message-id']='<new@outside.test>';unset($new['headers']['in-reply-to']);$pending=Reception::ingest($db,$owner,99,6,$new,$storage);checkRN($pending['auto_reply']&&$pending['user_id']===0,'new contact enters reception awaiting a choice');$calls=0;$send=function($to,$subject,$body,$thread)use(&$calls){$calls++;checkRN($thread['auto_reply']&&str_contains($body,'Responde'),'automatic prompt includes reply instructions and auto-reply metadata');return '<prompt@example.test>';};ReceptionWorker::autoReply($db,$owner,['email'=>'communications@example.test'],$pending,$storage,$send);ReceptionWorker::autoReply($db,$owner,['email'=>'communications@example.test'],$pending,$storage,$send);checkRN($calls===1,'first-contact automatic response is sent once');$choice=$new;$choice['headers']['message-id']='<choice@outside.test>';$choice['headers']['in-reply-to']='<prompt@example.test>';$choice['body']='Jose Contador';$assigned=Reception::ingest($db,$owner,99,7,$choice,$storage);checkRN($assigned['user_id']===1&&Reception::read($db,6,1)!==null,'client choice assigns both pending original and reply to employee');
$auto=$new;$auto['headers']['message-id']='<automatic@outside.test>';$auto['headers']['from']='robot@outside.test';$auto['headers']['auto-submitted']='auto-replied';checkRN(!Reception::ingest($db,$owner,99,8,$auto,$storage)['auto_reply'],'automatic messages cannot start auto-response loops');$db->exec("UPDATE users SET display_name='Same' WHERE id IN (1,2)");checkRN(Reception::resolveChoice($db,'Same')===0,'ambiguous employee names remain pending');
$admin=['role'=>'admin','id'=>1,'principal'=>'admin:1','name'=>'Admin'];$reader=['role'=>'employee','id'=>1,'principal'=>'employee:1','name'=>'Jose'];$other=['role'=>'employee','id'=>2,'principal'=>'employee:2','name'=>'Carlos'];Board::init($db);checkRN(!Board::canPublish($db,$reader),'ordinary users cannot publish without permission');try{Board::create($db,$reader,'Denied','<p>Test</p>','info',false);throw new LogicException('Publish bypass');}catch(InvalidArgumentException $e){}Board::grant($db,$admin,1,true);$post=Board::create($db,$reader,'Aviso','<p><b>Important</b></p><script>bad()</script>','security',true);checkRN(!str_contains(Board::post($db,$post)['body'],'script'),'notice rich text is sanitized');Board::comment($db,$other,$post,'<p>Comentario</p>');checkRN((int)$db->query('SELECT count(*) FROM notice_comments')->fetchColumn()===1,'readers can comment without publishing permission');Board::pin($db,$other,$post,false,true);checkRN((int)$db->query("SELECT count(*) FROM notice_pins WHERE principal='employee:2'")->fetchColumn()===1,'reader pins are personal');try{Board::pin($db,$other,$post,true,false);throw new LogicException('Global pin bypass');}catch(InvalidArgumentException $e){}checkRN(Board::post($db,$post)['author_pin']===1,'reader cannot change author global pin');checkRN(Board::unread($db,'employee:2')===1,'new notice contributes to notification count');Board::seen($db,'employee:2');checkRN(Board::unread($db,'employee:2')===0,'opening board clears notice notification');Board::grant($db,$admin,1,false);checkRN(!Board::canPublish($db,$reader),'admin can revoke notice publication permission');

$htmlChoice=$new;$htmlChoice['headers']['from']='htmlclient@outside.test';$htmlChoice['headers']['message-id']='<htmlchoice@outside.test>';$htmlChoice['plain']=false;$htmlChoice['body']='carlos@example.testQuoted old';$htmlChoice['html']='<div>carlos@example.test</div><blockquote><p>Quoted old</p></blockquote>';checkRN(Reception::ingest($db,$owner,99,9,$htmlChoice,$storage)['user_id']===2,'HTML-only selection preserves line boundaries before matching');$spam=$new;$spam['headers']['from']='spam@outside.test';$spam['headers']['message-id']='<spam@outside.test>';$spam['headers']['x-spam-flag']='YES';checkRN(!Reception::ingest($db,$owner,99,10,$spam,$storage)['auto_reply'],'provider spam flags suppress automatic prompts');
